PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS erp_citizens(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,name TEXT NOT NULL,email TEXT,phone TEXT,document_hash TEXT,neighborhood TEXT,city TEXT,state TEXT,tags TEXT DEFAULT '[]',consent_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_citizens_office_name ON erp_citizens(office_id,name);
CREATE TABLE IF NOT EXISTS erp_demands(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,citizen_id TEXT REFERENCES erp_citizens(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT DEFAULT '',category TEXT DEFAULT 'geral',priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('baixa','normal','alta','urgente')),status TEXT NOT NULL DEFAULT 'aberta' CHECK(status IN('aberta','triagem','em_andamento','aguardando','resolvida','arquivada')),assignee_id TEXT,due_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_demands_office_status ON erp_demands(office_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS erp_services(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,citizen_id TEXT REFERENCES erp_citizens(id) ON DELETE SET NULL,demand_id TEXT REFERENCES erp_demands(id) ON DELETE SET NULL,channel TEXT NOT NULL DEFAULT 'presencial',notes TEXT DEFAULT '',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_events(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',starts_at TEXT NOT NULL,ends_at TEXT,location TEXT,owner_id TEXT,status TEXT NOT NULL DEFAULT 'confirmado',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_events_office_start ON erp_events(office_id,starts_at);
CREATE TABLE IF NOT EXISTS erp_projects(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'planejamento',owner_id TEXT,budget_cents INTEGER DEFAULT 0,starts_at TEXT,due_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS erp_audit(id TEXT PRIMARY KEY,office_id TEXT NOT NULL,user_id TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,metadata TEXT DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_erp_audit_office_date ON erp_audit(office_id,created_at DESC);
